// No page on the public estate may be an auto-generated stub.
//
// On 2026-09-03 the agentic-fix engine's empty-page "fixer" overwrote nine
// working files because each was under 1 KB:
//
//   public/interop/swift/index.html            579 B  — a meta-refresh redirect
//   public/interop/xrpl/index.html             583 B  — a meta-refresh redirect
//   public/interop/incident/index.html         612 B  — a meta-refresh redirect
//   public/interop/xrpl-toml-gap/index.html    628 B  — a meta-refresh redirect
//   public/interop/swift-census/index.html     649 B  — a meta-refresh redirect
//   public/interop/incident-openai-hf/…        668 B  — a meta-refresh redirect
//   public/interop/gpai-signatory-2026-09/…    967 B  — a meta-refresh redirect
//   public/globe.html                          929 B
//   public/embed/spray-demo.html              1006 B  — the spray embed demo
//
// Size is not a defect signal. A redirect page is ~580 bytes BY DESIGN, and the
// spray demo is small because a minimal example is the entire point. Seven of
// the nine were /interop/ evidence surfaces — SWIFT, XRPL, GPAI, the OpenAI
// incident — replaced with a page reading "Auto-generated stub".
//
// This test exists so that never ships. A measurement body cannot publish
// auto-generated filler where evidence used to be.
import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { globSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const PUBLIC = join(dirname(fileURLToPath(import.meta.url)));

describe("the public estate carries no auto-generated stubs", () => {
  it("no published page says it was auto-generated", () => {
    const files = globSync("**/*.html", { cwd: PUBLIC });
    const offenders = files.filter((f) => {
      const t = readFileSync(join(PUBLIC, f), "utf8");
      return /Auto-generated stub|auto-generated by the CSOAI agentic-fix/i.test(t);
    });
    expect(offenders).toEqual([]);
  });

  it("the three interop redirects still redirect", () => {
    for (const p of [
      "interop/swift/index.html",
      "interop/xrpl/index.html",
      "interop/incident/index.html",
    ]) {
      const t = readFileSync(join(PUBLIC, p), "utf8");
      // ~580 bytes BY DESIGN — a meta-refresh page is supposed to be tiny
      expect(t).toMatch(/http-equiv="refresh"/i);
      expect(t).not.toMatch(/Auto-generated/i);
    }
  });

  it("the four small interop evidence pages still carry their evidence", () => {
    // These are not redirects. They are short because the fact is short.
    const must = {
      "interop/gpai-signatory-2026-09/index.html": /not a GPAI Code signatory/i,
      "interop/incident-openai-hf/index.html": /incident/i,
      "interop/xrpl-toml-gap/index.html": /xrpl|toml/i,
      "interop/swift-census/index.html": /swift/i,
    };
    for (const [p, re] of Object.entries(must)) {
      const t = readFileSync(join(PUBLIC, p), "utf8");
      expect(t, `${p} lost its content`).toMatch(re);
      expect(t).not.toMatch(/Auto-generated/i);
    }
  });

  it("the spray embed demo still embeds", () => {
    const t = readFileSync(join(PUBLIC, "embed/spray-demo.html"), "utf8");
    expect(t).toMatch(/<iframe/i);
    expect(t).toMatch(/embed\/verify/);
    expect(t).not.toMatch(/Auto-generated/i);
  });
});
